def mse(w, b, xs, ys):
    total = 0
    for i in range(len(xs)):
        e = w * xs[i] + b - ys[i]
        total = total + e * e
    return total / len(xs)

def fit_halving(xs, ys):
    w, b = 0.0, 0.0
    for step in [1, 0.5, 0.25, 0.125]:
        while True:
            old = (w, b)
            best = mse(w, b, xs, ys)
            up, down = mse(w + step, b, xs, ys), mse(w - step, b, xs, ys)
            if up < best and up <= down:
                w, best = w + step, up
            elif down < best:
                w, best = w - step, down
            up, down = mse(w, b + step, xs, ys), mse(w, b - step, xs, ys)
            if up < best and up <= down:
                b, best = b + step, up
            elif down < best:
                b, best = b - step, down
            if (w, b) == old:
                break
    return (w, b, round(mse(w, b, xs, ys), 6))

