def sample_name(names, us):
    counts = {}
    for name in names:
        marked = '.' + name + '.'
        for i in range(len(marked) - 1):
            row = counts.setdefault(marked[i], {})
            row[marked[i + 1]] = row.get(marked[i + 1], 0) + 1
    letter, out = '.', ''
    for u in us:
        row = counts[letter]
        total = sum(row.values())
        running = 0
        for nxt in sorted(row):
            running = running + row[nxt]
            if running > u * total:
                break
        if nxt == '.':
            break
        out += nxt
        letter = nxt
    return out

